import re

_TASHKEEL = re.compile("[ً-ِ]")


def strip_tashkeel(text: str) -> str:
    """يحذف كلَّ علامات التشكيل: الفتحةَ والضمةَ والكسرة، والتنوينَ بأنواعه،
    والشدّةَ والسكون، والألفَ الخنجرية (ٰ). ولا يمسّ الحروف."""
    return _TASHKEEL.sub("", text)

