_EASTERN = "٠١٢٣٤٥٦٧٨٩"


def to_western(text: str) -> str:
    """يحوّل الأرقامَ العربية المشرقية في النص إلى أرقامٍ غربية، ولا يمسّ غيرَها."""
    return text.translate(str.maketrans(_EASTERN, "0123456789"))

