class Inventory:
    """مخزونٌ بسيط: اسمُ الصنف وكميّتُه."""

    def __init__(self):
        self._items = {}

    def add(self, name, quantity):
        if quantity <= 0:
            raise ValueError("الكميّةُ موجبة")
        self._items[name] = self._items.get(name, 0) + quantity

    def quantity(self, name):
        return self._items.get(name, 0)

