workspace.src/shipping.py:
def cost(zone, weight_kg):
    """أجرةُ الشحن بالريال: سعرُ المنطقة للكيلو مضروبًا في الوزن، وحدٌّ أدنى ١٥ ريالًا."""
    if zone == "الوسطى":
        rate = 4
    elif zone == "الغربية":
        rate = 5
    elif zone == "الشرقية":
        rate = 5
    elif zone == "الشمالية":
        rate = 7
    elif zone == "الجنوبية":
        rate = 6
    else:
        raise ValueError(f"منطقةٌ غير معروفة: {zone}")
    return max(15, rate * weight_kg)

