workspace.src/stats.py:
def mean(values):
    return sum(values) / len(values)


def variance(values):
    """تباينُ العيّنة: مجموعُ مربّعات الانحراف مقسومًا على (n - 1)."""
    m = mean(values)
    return sum((v - m) ** 2 for v in values) / len(values) - 1


def std(values):
    return variance(values) ** 0.5

